#!/usr/bin/env bash
#
# 検出器(`.claude/hooks/lib/*.py`)を呼ぶ検査の前提チェック。source して使う。
#
# `check-added-*.sh` は検出器の出力が空なら「ありません」と出して exit 0 になる。
# **検出器を走らせられなかったときも出力は空になる**ので、そのままでは「検査したが
# 0 件」と「検査できなかった」が同じ綴り・同じ終了コードになる。
#
# ここが見るのは**走らせられるか**まで(python3 の疎通・検出器ファイルの存在)。
# 起動したあとに検出器自身が異常終了する場合は、終了コードが違反ありと同じ 1 になるので
# ここでは見分けられず、いまも「ありません」で通る。そちらは別の判断として分けてある。
#
# 前提チェックを通る検査の終了コードは 3 値:
#   0  違反なし(検査した)
#   1  違反あり
#   2  検査できなかった(python3 が使えない / 検出器が見つからない)
#
# 呼び出し側は 1 と 2 をどちらも赤として扱う。それでも分けるのは、ログを読む人が理由を
# 区別できるようにするためと、判定表(`check-added-cases.sh`)がこの 2 つを別のケースと
# して固定できるようにするため。
#
# **`command -v python3` では見分けられない。** PATH に居るが起動すると落ちる python3 は
# `command -v` に見つかるので前提チェックが通り、偽の緑がそのまま残る。1 回起動して見る。
#
# 層ごとの扱いは `harness/githooks/README.md`「何が走るか」。

# python3 が実際に起動できるか。
python3_usable() {
  python3 -c '' >/dev/null 2>&1
}

# 検査を走らせられないなら、理由を出して exit 2。
#
# @param 1 検査の名前。出力に出すので、呼び出し側の見出しと同じ綴りにする
# @param 2 その検査が呼ぶ検出器のパス(リポジトリ top からの相対)
require_runnable_detector() {
  local check="$1" detector="$2"

  if ! python3_usable; then
    echo "${check}: python3 が使えないため検査できません(検査していないものを緑にしない)" >&2
    exit 2
  fi

  if [ ! -f "$detector" ]; then
    echo "${check}: 検出器 ${detector} が見つからないため検査できません" >&2
    exit 2
  fi
}
